/**
 * VersionKind — вид снимка. От него зависит, хранится ли снимок всегда.
 */
export type VersionKind = string;
export const VersionCreate: VersionKind = "create"; // документ создан
export const VersionAutosave: VersionKind = "autosave"; // автосохранение редактора (не применяется к документу)
export const VersionSave: VersionKind = "save"; // сохранение черновика или документа на проверке
export const VersionEdit: VersionKind = "edit"; // правка опубликованного или архивного «на месте»
export const VersionStatus: VersionKind = "status"; // смена статуса
export const VersionImport: VersionKind = "import"; // загрузка из файла командой kupol doc import
export const VersionRollback: VersionKind = "rollback"; // откат к прежней версии
/**
 * MaxRollingVersions — сколько скользящих снимков хранится на документ.
 */
export const MaxRollingVersions = 30;
/**
 * Version — снимок документа (таблица document_versions).
 */
export interface Version {
  ID: number /* int64 */;
  DocumentID: number /* int64 */;
  Revision: number /* int */;
  Kind: string;
  Status: string;
  Permanent: boolean;
  AuthorID?: number /* int64 */;
  Note: string;
  Content: JSONText;
  CreatedAt: string /* RFC 3339 */;
}
/**
 * VersionItem — строка истории.
 */
export interface VersionItem {
  id: number /* int64 */;
  revision: number /* int */;
  kind: string;
  kind_name: string;
  status: string;
  permanent: boolean;
  author?: string;
  note?: string;
  created_at: string /* RFC 3339 */;
}
/**
 * VersionsPage — страница истории (новые сверху).
 */
export interface VersionsPage {
  items: VersionItem[];
  total: number /* int64 */;
  page: number /* int */;
  per_page: number /* int */;
  pages: number /* int */;
}
/**
 * VersionFull — снимок целиком.
 */
export interface VersionFull extends VersionItem {
  content: Content;
}
/**
 * FieldChange — изменённое поле документа (название, допуск, дата, свойства).
 */
export interface FieldChange {
  field: string;
  label: string;
  before: unknown;
  after: unknown;
}
/**
 * BlockChange — изменение блока. Change: added, removed, changed, moved.
 */
export interface BlockChange {
  id: string;
  type: string;
  change: string;
  before?: InputBlock;
  after?: InputBlock;
}
/**
 * Diff — разница двух содержимых по блокам и полям.
 */
export interface Diff {
  fields: FieldChange[];
  blocks: BlockChange[];
  unchanged_blocks: number /* int */;
  same: boolean;
}

